W=$(realpath ../clone-work/scratch) && cat > $W/probe.ts <<'EOF'
import { Hono } from 'SRC/index'
import { validator } from 'SRC/validator'
import { parseBody } from 'SRC/utils/body'
import { cloneRawRequest } from 'SRC/request'

const run = async (name: string, fn: () => Promise<unknown>) => {
  try {
    const r = await fn()
    console.log(name, '=>', JSON.stringify(r))
  } catch (e) {
    console.log(name, '=> THROW', (e as Error).name, (e as Error).message)
  }
}

const mk = (kind: 'multi' | 'url', ct?: string) => {
  let body: BodyInit
  if (kind === 'multi') {
    const fd = new FormData()
    fd.append('message', 'hello')
    fd.append('n', '1')
    body = fd
  } else {
    body = new URLSearchParams({ message: 'hello', n: '1' })
  }
  const init: RequestInit = { method: 'POST', body }
  if (ct) init.headers = { 'Content-Type': ct }
  return new Request('http://localhost/', init)
}

const appWith = (h: (c: any) => Promise<unknown>) => {
  const app = new Hono()
  app.post('/', async (c) => {
    try {
      return c.json({ ok: await h(c) })
    } catch (e) {
      return c.json({ THROW: (e as Error).name + ': ' + (e as Error).message })
    }
  })
  return app
}
const fdObj = (fd: FormData) => Object.fromEntries([...fd.entries()].map(([k, v]) => [k, typeof v === 'string' ? v : 'FILE']))

for (const kind of ['multi', 'url'] as const) {
  await run(`[${kind}] formData() then parseBody()`, async () => {
    const app = appWith(async (c) => {
      const fd = await c.req.formData()
      const pb = await c.req.parseBody()
      let after: unknown
      try { after = fdObj(await c.req.formData()) } catch (e) { after = 'THROW ' + (e as Error).message }
      return { fd: fdObj(fd), pb, after }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] parseBody() then formData()`, async () => {
    const app = appWith(async (c) => {
      const pb = await c.req.parseBody()
      const fd = await c.req.formData()
      return { fd: fdObj(fd), pb }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] parseBody() x2`, async () => {
    const app = appWith(async (c) => {
      const pb = await c.req.parseBody()
      const pb2 = await c.req.parseBody()
      return { pb, pb2 }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] concurrent parseBody()+formData()`, async () => {
    const app = appWith(async (c) => {
      const [pb, fd] = await Promise.all([c.req.parseBody(), c.req.formData()])
      return { fd: fdObj(fd), pb }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] concurrent formData()+parseBody()`, async () => {
    const app = appWith(async (c) => {
      const [fd, pb] = await Promise.all([c.req.formData(), c.req.parseBody()])
      return { fd: fdObj(fd), pb }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] text() then parseBody()`, async () => {
    const app = appWith(async (c) => {
      await c.req.text()
      return await c.req.parseBody()
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] blob() then parseBody()`, async () => {
    const app = appWith(async (c) => {
      await c.req.blob()
      return await c.req.parseBody()
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] arrayBuffer() then parseBody()`, async () => {
    const app = appWith(async (c) => {
      await c.req.arrayBuffer()
      return await c.req.parseBody()
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] parseBody() then text()`, async () => {
    const app = appWith(async (c) => {
      const pb = await c.req.parseBody()
      const t = await c.req.text()
      return { pb, tlen: t.length }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] parseBody() then cloneRawRequest().formData()`, async () => {
    const app = appWith(async (c) => {
      const pb = await c.req.parseBody()
      const cl = await cloneRawRequest(c.req)
      return { pb, cl: fdObj(await cl.formData()) }
    })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] formData() then validator-form then parseBody`, async () => {
    const app = new Hono()
    app.post('/', async (c, next) => { await c.req.formData(); await next() },
      validator('form', (v) => v),
      async (c) => {
        try { return c.json({ v: c.req.valid('form'), pb: await c.req.parseBody() }) } catch (e) { return c.json({ THROW: (e as Error).message }) }
      })
    return (await app.request(mk(kind))).json()
  })
  await run(`[${kind}] parseBody then validator-form`, async () => {
    const app = new Hono()
    app.post('/', async (c, next) => { await c.req.parseBody(); await next() },
      validator('form', (v) => v),
      async (c) => c.json({ v: c.req.valid('form') }))
    return (await app.request(mk(kind))).json()
  })
}

// Plain Request
await run('plain Request multi', async () => parseBody(mk('multi')))
await run('plain Request url', async () => parseBody(mk('url')))
// Content-type variants
for (const ct of [
  'application/x-www-form-urlencoded',
  'Application/X-WWW-Form-Urlencoded',
  'application/x-www-form-urlencoded;charset=UTF-8',
  'application/x-www-form-urlencoded ; charset=UTF-8',
  'application/x-www-form-urlencoded charset=UTF-8',
  'application/x-www-form-urlencoded, application/x-www-form-urlencoded',
  'application/x-www-form-urlencodedx',
  'multipart/form-data-foo',
  'text/plain',
]) {
  await run(`plain url ct=${ct}`, async () => parseBody(mk('url', ct)))
}
// no body
await run('GET no body urlencoded', async () => parseBody(new Request('http://localhost/', { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } })))
await run('GET no body multipart', async () => parseBody(new Request('http://localhost/', { headers: { 'Content-Type': 'multipart/form-data; boundary=abc' } })))
await run('POST empty multipart', async () => parseBody(new Request('http://localhost/', { method: 'POST', body: '', headers: { 'Content-Type': 'multipart/form-data; boundary=abc' } })))
await run('POST multipart no boundary param', async () => parseBody(new Request('http://localhost/', { method: 'POST', body: 'x', headers: { 'Content-Type': 'multipart/form-data' } })))
// charset
await run('urlencoded body with non-utf8 charset', async () => parseBody(new Request('http://localhost/', { method: 'POST', body: 'a=%E3%81%82', headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=Shift_JIS' } })))
// File
await run('file multipart', async () => {
  const fd = new FormData()
  fd.append('f', new File(['abc'], 'a.txt', { type: 'text/plain' }))
  const r = await parseBody(new Request('http://localhost/', { method: 'POST', body: fd }))
  const f = r.f as File
  return { isFile: f instanceof File, name: f.name, type: f.type, size: f.size, text: await f.text() }
})
// subclassed request overriding formData
await run('Request subclass overriding formData', async () => {
  class R extends Request { async formData() { const f = new FormData(); f.append('custom', 'yes'); return f } }
  return parseBody(new R('http://localhost/', { method: 'POST', body: 'a=b', headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }))
})
EOF
for v in base head; do sed "s#SRC#$W/$v/src#" $W/probe.ts > $W/probe-$v.ts; ./node_modules/.bin/esbuild $W/probe-$v.ts --bundle --platform=node --format=esm --outfile=$W/probe-$v.mjs --log-level=error; node $W/probe-$v.mjs > $W/out-$v.txt 2>&1; done; diff $W/out-base.txt $W/out-head.txt; echo ======; cat $W/out-head.txt

W=$(realpath ../clone-work/scratch) && cat > $W/mem.ts <<'EOF'
import { Hono } from 'SRC/index'
const MB = 1024 * 1024
const size = 150 * MB
const fd = new FormData()
fd.append('f', new File([new Uint8Array(size)], 'big.bin', { type: 'application/octet-stream' }))
const src = new Request('http://localhost/', { method: 'POST', body: fd })
const ct = src.headers.get('Content-Type')!
const bytes = await src.arrayBuffer()
const app = new Hono()
let peak = 0
const sample = () => { const m = process.memoryUsage(); peak = Math.max(peak, m.arrayBuffers + m.external) }
const iv = setInterval(sample, 2)
app.post('/', async (c) => {
  ;(globalThis as any).gc?.()
  const before = process.memoryUsage()
  const t0 = performance.now()
  const body = await c.req.parseBody()
  const t1 = performance.now()
  sample()
  ;(globalThis as any).gc?.()
  await new Promise((r) => setTimeout(r, 50))
  ;(globalThis as any).gc?.()
  const after = process.memoryUsage()
  const t2 = performance.now()
  await c.req.parseBody()
  const t3 = performance.now()
  return c.json({
    fileSize: (body.f as File).size / MB,
    retainedArrayBuffersMB: Math.round((after.arrayBuffers - before.arrayBuffers) / MB),
    retainedRssMB: Math.round((after.rss - before.rss) / MB),
    firstParseMs: Math.round(t1 - t0),
    secondParseMs: Math.round(t3 - t2),
    cacheKeys: Object.keys(c.req.bodyCache),
  })
})
const res = await app.request(new Request('http://localhost/', { method: 'POST', body: bytes, headers: { 'Content-Type': ct } }))
clearInterval(iv)
console.log(JSON.stringify(await res.json()), 'peakRssMB', Math.round(process.resourceUsage().maxRSS / 1024))
EOF
for v in base head; do sed "s#SRC#$W/$v/src#" $W/mem.ts > $W/mem-$v.ts; ./node_modules/.bin/esbuild $W/mem-$v.ts --bundle --platform=node --format=esm --outfile=$W/mem-$v.mjs --log-level=error; echo $v; node --expose-gc $W/mem-$v.mjs; done
